package hu.synostream.android;
import org.junit.*;import static org.junit.Assert.*;import java.util.*;import java.util.concurrent.*;
public class SessionRetirementTest {
 NasClientTest fixture;
 @Before public void start()throws Exception{fixture=new NasClientTest();fixture.start();fixture.expire=false;}
 @After public void stop()throws Exception{fixture.stop();}
 @Test public void threeReconnectionsAndLogoutCloseEverySessionExactlyOnce()throws Exception{NasClient root=fixture.client();for(int i=0;i<3;i++){NasClient next=root.reconnectCandidate(false);assertTrue(root.installConnection(root.suspendConnection(),next));root.retireSuperseded();}assertEquals(4,fixture.logins);assertEquals(3,fixture.logouts);root.logout();assertEquals(4,fixture.logouts);root.logout();root.retireSuperseded();assertEquals(4,fixture.logouts);}
 @Test public void logoutWithoutEarlierCleanupIncludesOwnCurrentAndAllRetired()throws Exception{NasClient root=fixture.client();for(int i=0;i<3;i++)root.installConnection(root.suspendConnection(),root.reconnectCandidate(false));assertEquals(0,fixture.logouts);root.logout();assertEquals(fixture.logins,fixture.logouts);}
 @Test public void cleanupWaitsForInjectedGraceAndLeavesActiveSessionUsable()throws Exception{NasClient root=fixture.client();NasClient previous=root.reconnectCandidate(false);root.installConnection(root.suspendConnection(),previous);List<Runnable> delayed=new ArrayList<>();List<Runnable> io=new ArrayList<>();SessionRetirement timer=new SessionRetirement((work,millis)->{assertEquals(30000,millis);delayed.add(work);});NasClient next=root.reconnectCandidate(false);assertTrue(timer.install(root,root.suspendConnection(),next,io::add));assertEquals(0,fixture.logouts);try(NasClient.Stream s=previous.stream("/video/A.mkv",null,false)){assertArrayEquals(new byte[]{2,3,4},s.body.readAllBytes());}delayed.get(0).run();assertEquals(0,fixture.logouts);io.get(0).run();assertEquals(2,fixture.logouts);assertEquals(3,root.list("/video").size());root.logout();assertEquals(3,fixture.logouts);}
 @Test public void rejectedInstallLogsOutCandidateOnTheProvidedExecutor()throws Exception{NasClient root=fixture.client(),candidate=root.reconnectCandidate(false);int old=root.suspendConnection();root.suspendConnection();List<Runnable> io=new ArrayList<>();SessionRetirement timer=new SessionRetirement((work,millis)->fail("No retirement for a rejected install"));assertFalse(timer.install(root,old,candidate,io::add));assertEquals(0,fixture.logouts);io.get(0).run();assertEquals(1,fixture.logouts);root.logout();assertEquals(2,fixture.logouts);}
 @Test public void repeatedLogoutDoesNotIssueAnotherRequest()throws Exception{NasClient root=fixture.client();root.logout();root.logout();assertEquals(1,fixture.logouts);}
 @Test public void repeatedRetirementDoesNotLogoutCurrentReplacement()throws Exception{NasClient root=fixture.client();root.installConnection(root.suspendConnection(),root.reconnectCandidate(false));root.retireSuperseded();root.retireSuperseded();assertEquals(1,fixture.logouts);root.logout();assertEquals(2,fixture.logouts);}
 @Test public void newerReplacementGetsItsFullGracePeriod()throws Exception{NasClient root=fixture.client();List<Runnable> delayed=new ArrayList<>();SessionRetirement timer=new SessionRetirement((work,millis)->delayed.add(work));timer.install(root,root.suspendConnection(),root.reconnectCandidate(false),Runnable::run);timer.install(root,root.suspendConnection(),root.reconnectCandidate(false),Runnable::run);delayed.get(0).run();assertEquals(0,fixture.logouts);delayed.get(1).run();assertEquals(2,fixture.logouts);root.logout();assertEquals(3,fixture.logouts);}
 @Test public void requestStartedOnOldSessionCompletesBeforeDeferredCleanup()throws Exception{NasClient root=fixture.client();NasClientTest other=new NasClientTest();other.start();other.expire=false;ExecutorService io=Executors.newSingleThreadExecutor();fixture.holdList=true;List<Runnable> delayed=new ArrayList<>();try{Future<Integer> request=io.submit(()->root.list("/video").size());assertTrue(fixture.listEntered.await(2,TimeUnit.SECONDS));NasClient next=other.client();SessionRetirement timer=new SessionRetirement((work,millis)->delayed.add(work));assertTrue(timer.install(root,root.suspendConnection(),next,Runnable::run));assertFalse(request.isDone());assertEquals(0,fixture.logouts);fixture.releaseList.countDown();assertEquals(3,request.get(3,TimeUnit.SECONDS).intValue());delayed.get(0).run();assertEquals(1,fixture.logouts);assertEquals(0,other.logouts);root.logout();assertEquals(1,other.logouts);}finally{fixture.releaseList.countDown();io.shutdownNow();other.stop();}}

 @Test public void staleRetirementRevisionCannotCloseRecentlyReplacedSession()throws Exception{NasClient root=fixture.client();root.installConnection(root.suspendConnection(),root.reconnectCandidate(false));int before=root.retirementRevision();root.installConnection(root.suspendConnection(),root.reconnectCandidate(false));root.retireSuperseded(before);assertEquals(0,fixture.logouts);root.retireSuperseded(root.retirementRevision());assertEquals(2,fixture.logouts);root.logout();assertEquals(3,fixture.logouts);}

}
